import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.OptionalLong;
import java.util.TreeMap;
import java.util.function.LongSupplier;

public class Solution {
    /** Um item entregue à aplicação: dados em ordem, ou o aviso de que um número de sequência foi dado como perdido. */
    static final class Entrega {
        enum Tipo { DADOS, PERDA }

        private final Tipo tipo;
        private final long seq;
        private final String dados;

        private Entrega(Tipo tipo, long seq, String dados) {
            this.tipo = tipo;
            this.seq = seq;
            this.dados = dados;
        }

        static Entrega dados(long seq, String dados) {
            return new Entrega(Tipo.DADOS, seq, dados);
        }

        static Entrega perda(long seq) {
            return new Entrega(Tipo.PERDA, seq, null);
        }

        Tipo tipo() { return tipo; }
        long seq() { return seq; }
        String dados() { return dados; }

        @Override public boolean equals(Object o) {
            return o instanceof Entrega e && e.tipo == tipo && e.seq == seq && Objects.equals(e.dados, dados);
        }

        @Override public int hashCode() { return Objects.hash(tipo, seq, dados); }

        @Override public String toString() {
            return tipo == Tipo.PERDA ? "PERDA(" + seq + ")" : "DADOS(" + seq + ", " + dados + ")";
        }
    }

    static final class BufferDeJitter {
        private record Pendente(String dados, long chegada) {}

        private final long prazoMs;
        private final int janela;
        private final LongSupplier relogio;
        private final TreeMap<Long, Pendente> espera = new TreeMap<>();
        private long proxima = 0;
        private long perdas = 0;
        private long descartados = 0;

        BufferDeJitter(long prazoMs, int janela, LongSupplier relogio) {
            if (prazoMs < 0) throw new IllegalArgumentException("prazo negativo");
            if (janela < 1) throw new IllegalArgumentException("janela precisa ser >= 1");
            if (relogio == null) throw new IllegalArgumentException("relógio nulo");
            this.prazoMs = prazoMs;
            this.janela = janela;
            this.relogio = relogio;
        }

        boolean receber(long seq, String dados) {
            if (seq < 0) throw new IllegalArgumentException("seq negativo");
            if (dados == null) throw new IllegalArgumentException("dados nulos");
            if (seq < proxima || seq - proxima >= janela || espera.containsKey(seq)) {
                descartados++;
                return false;
            }
            espera.put(seq, new Pendente(dados, relogio.getAsLong()));
            return true;
        }

        List<Entrega> retirar() {
            long agora = relogio.getAsLong();
            List<Entrega> saida = new ArrayList<>();
            while (!espera.isEmpty()) {
                Pendente p = espera.remove(proxima);
                if (p != null) {
                    saida.add(Entrega.dados(proxima, p.dados()));
                    proxima++;
                    continue;
                }
                if (agora - maisAntiga() < prazoMs) break;
                long ate = espera.firstKey();            // toda a lacuna antes dele venceu junto
                for (; proxima < ate; proxima++) {
                    saida.add(Entrega.perda(proxima));
                    perdas++;
                }
            }
            return saida;
        }

        OptionalLong proximoVencimento() {
            if (espera.isEmpty() || espera.containsKey(proxima)) return OptionalLong.empty();
            return OptionalLong.of(maisAntiga() + prazoMs);
        }

        int emEspera() { return espera.size(); }
        long proximaEsperada() { return proxima; }
        long totalPerdas() { return perdas; }
        long totalDescartados() { return descartados; }

        private long maisAntiga() {
            long min = Long.MAX_VALUE;
            for (Pendente p : espera.values()) min = Math.min(min, p.chegada());
            return min;
        }
    }
}

