import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.OptionalLong;
import java.util.Random;
import java.util.function.LongSupplier;

class SolutionTest {
    static final class Relogio implements LongSupplier {
        long agora = 0;
        @Override public long getAsLong() { return agora; }
        Relogio em(long t) { agora = t; return this; }
    }

    static Solution.Entrega d(long seq, String dados) { return Solution.Entrega.dados(seq, dados); }
    static Solution.Entrega p(long seq) { return Solution.Entrega.perda(seq); }

    // ---------- entrega em ordem ----------

    @Test void pacotesEmOrdemSaemNaHora() {
        Relogio t = new Relogio();
        Solution.BufferDeJitter b = new Solution.BufferDeJitter(50, 100, t);
        assertTrue(b.receber(0, "a"));
        assertTrue(b.receber(1, "b"));
        assertTrue(b.receber(2, "c"));
        assertEquals(List.of(d(0, "a"), d(1, "b"), d(2, "c")), b.retirar());
        assertEquals(0, b.emEspera());
        assertEquals(3, b.proximaEsperada());
    }

    @Test void semNadaParaEntregarDevolveListaVazia() {
        Solution.BufferDeJitter b = new Solution.BufferDeJitter(50, 100, new Relogio());
        assertTrue(b.retirar().isEmpty());
        assertEquals(0, b.proximaEsperada());
    }

    @Test void foraDeOrdemFicaSeguroAteChegarOQueFalta() {
        Relogio t = new Relogio();
        Solution.BufferDeJitter b = new Solution.BufferDeJitter(50, 100, t);
        b.receber(0, "a");
        b.receber(2, "c");
        assertEquals(List.of(d(0, "a")), b.retirar());
        assertEquals(1, b.emEspera());
        assertEquals(1, b.proximaEsperada());

        t.em(20);
        b.receber(1, "b");
        assertEquals(List.of(d(1, "b"), d(2, "c")), b.retirar());
        assertEquals(0, b.emEspera());
        assertEquals(0, b.totalPerdas());
    }

    @Test void chegadaTotalmenteInvertidaSaiOrdenada() {
        Solution.BufferDeJitter b = new Solution.BufferDeJitter(50, 100, new Relogio());
        for (int s = 3; s >= 1; s--) b.receber(s, "x" + s);
        assertTrue(b.retirar().isEmpty());
        b.receber(0, "x0");
        assertEquals(List.of(d(0, "x0"), d(1, "x1"), d(2, "x2"), d(3, "x3")), b.retirar());
    }

    // ---------- perdas e prazo ----------

    @Test void lacunaVencidaViraPerdaEOPacoteSeguinteEEntregue() {
        Relogio t = new Relogio();
        Solution.BufferDeJitter b = new Solution.BufferDeJitter(50, 100, t);
        b.receber(0, "a");
        t.em(10);
        b.receber(2, "c");
        assertEquals(List.of(d(0, "a")), b.retirar());

        t.em(59);
        assertTrue(b.retirar().isEmpty(), "ainda dentro do prazo");
        t.em(60);
        assertEquals(List.of(p(1), d(2, "c")), b.retirar(), "o prazo vale a partir da chegada do pacote 2, e vence em 10 + 50");
        assertEquals(1, b.totalPerdas());
        assertEquals(3, b.proximaEsperada());
    }

    @Test void lacunaDeVariosPacotesVenceJunta() {
        Relogio t = new Relogio();
        Solution.BufferDeJitter b = new Solution.BufferDeJitter(50, 100, t);
        b.receber(0, "a");
        b.receber(4, "e");
        assertEquals(List.of(d(0, "a")), b.retirar());
        t.em(50);
        assertEquals(List.of(p(1), p(2), p(3), d(4, "e")), b.retirar());
        assertEquals(3, b.totalPerdas());
    }

    @Test void primeiroPacoteAusenteTambemEPerda() {
        Relogio t = new Relogio();
        Solution.BufferDeJitter b = new Solution.BufferDeJitter(30, 100, t);
        b.receber(2, "c");
        assertTrue(b.retirar().isEmpty());
        t.em(30);
        assertEquals(List.of(p(0), p(1), d(2, "c")), b.retirar());
    }

    @Test void prazoContaDaChegadaMaisAntigaNoBufferENaoDaMaisRecente() {
        Relogio t = new Relogio();
        Solution.BufferDeJitter b = new Solution.BufferDeJitter(50, 100, t);
        b.receber(0, "a");
        b.retirar();
        t.em(10);
        b.receber(2, "c");
        t.em(40);
        b.receber(3, "d");
        t.em(60);
        assertEquals(List.of(p(1), d(2, "c"), d(3, "d")), b.retirar(), "chegar o pacote 3 não pode reiniciar a espera pelo 1");
    }

    @Test void cadaLacunaTemOPrazoDoPacoteQueARevelou() {
        Relogio t = new Relogio();
        Solution.BufferDeJitter b = new Solution.BufferDeJitter(50, 100, t);
        b.receber(0, "a");
        t.em(10);
        b.receber(2, "c");
        assertEquals(List.of(d(0, "a")), b.retirar());
        t.em(40);
        b.receber(4, "e");

        t.em(60);
        assertEquals(List.of(p(1), d(2, "c")), b.retirar(), "o pacote 3 só falta desde o instante 40");
        assertEquals(3, b.proximaEsperada());
        t.em(89);
        assertTrue(b.retirar().isEmpty());
        t.em(90);
        assertEquals(List.of(p(3), d(4, "e")), b.retirar());
        assertEquals(2, b.totalPerdas());
    }

    @Test void pacotesMisturadosDeVariasLacunasNumaSoChamada() {
        Relogio t = new Relogio();
        Solution.BufferDeJitter b = new Solution.BufferDeJitter(50, 100, t);
        b.receber(0, "a");
        b.retirar();
        t.em(10);
        b.receber(5, "f");
        t.em(40);
        b.receber(3, "d");
        t.em(60);
        assertEquals(List.of(p(1), p(2), d(3, "d"), p(4), d(5, "f")), b.retirar());
        assertEquals(3, b.totalPerdas());
    }

    @Test void prazoZeroDeclaraPerdaNaPrimeiraRetirada() {
        Solution.BufferDeJitter b = new Solution.BufferDeJitter(0, 100, new Relogio());
        b.receber(2, "c");
        assertEquals(List.of(p(0), p(1), d(2, "c")), b.retirar());
    }

    @Test void perdasDoFimDaTransmissaoNaoSaoDetectaveis() {
        Relogio t = new Relogio();
        Solution.BufferDeJitter b = new Solution.BufferDeJitter(50, 100, t);
        b.receber(0, "a");
        b.receber(1, "b");
        assertEquals(2, b.retirar().size());
        t.em(10_000);
        assertTrue(b.retirar().isEmpty(), "sem um pacote posterior não há como saber que o 2 existia");
        assertEquals(0, b.totalPerdas());
    }

    // ---------- descartes ----------

    @Test void pacoteQueChegaDepoisDeDeclaradoPerdidoEDescartado() {
        Relogio t = new Relogio();
        Solution.BufferDeJitter b = new Solution.BufferDeJitter(50, 100, t);
        b.receber(0, "a");
        b.receber(2, "c");
        b.retirar();
        t.em(50);
        assertEquals(List.of(p(1), d(2, "c")), b.retirar());

        assertFalse(b.receber(1, "tarde"));
        assertEquals(1, b.totalDescartados());
        assertTrue(b.retirar().isEmpty(), "um pacote perdido nunca é entregue depois");
        assertEquals(1, b.totalPerdas());
    }

    @Test void duplicadoEDescartadoEPrevaleceOPrimeiro() {
        Solution.BufferDeJitter b = new Solution.BufferDeJitter(50, 100, new Relogio());
        assertTrue(b.receber(2, "primeiro"));
        assertFalse(b.receber(2, "segundo"));
        assertEquals(1, b.emEspera());
        b.receber(0, "a");
        b.receber(1, "b");
        assertEquals(List.of(d(0, "a"), d(1, "b"), d(2, "primeiro")), b.retirar());
        assertEquals(1, b.totalDescartados());
    }

    @Test void pacoteJaEntregueNaoEntraDeNovo() {
        Solution.BufferDeJitter b = new Solution.BufferDeJitter(50, 100, new Relogio());
        b.receber(0, "a");
        b.retirar();
        assertFalse(b.receber(0, "a de novo"));
        assertEquals(0, b.emEspera());
        assertTrue(b.retirar().isEmpty());
    }

    @Test void pacoteMuitoAdiantadoSaiDaJanelaEEDescartado() {
        Solution.BufferDeJitter b = new Solution.BufferDeJitter(50, 4, new Relogio());
        assertTrue(b.receber(3, "d"));
        assertFalse(b.receber(4, "e"), "4 - 0 >= janela");
        assertEquals(1, b.totalDescartados());
        b.receber(0, "a");
        assertEquals(List.of(d(0, "a")), b.retirar());
        assertTrue(b.receber(4, "e"), "agora a próxima esperada é 1 e 4 - 1 < 4");
    }

    @Test void numerosGigantesNaoGeramMilhoesDePerdas() {
        Solution.BufferDeJitter b = new Solution.BufferDeJitter(50, 1000, new Relogio());
        assertFalse(b.receber(Long.MAX_VALUE, "x"));
        assertFalse(b.receber(5_000_000_000L, "y"));
        assertEquals(0, b.emEspera());
    }

    // ---------- vencimento ----------

    @Test void proximoVencimentoInformaQuandoALacunaVence() {
        Relogio t = new Relogio();
        Solution.BufferDeJitter b = new Solution.BufferDeJitter(50, 100, t);
        assertEquals(OptionalLong.empty(), b.proximoVencimento());
        t.em(10);
        b.receber(2, "c");
        assertEquals(OptionalLong.of(60), b.proximoVencimento());
        t.em(30);
        b.receber(0, "a");
        assertEquals(OptionalLong.empty(), b.proximoVencimento(), "o próximo esperado está no buffer: nada a esperar");
        b.retirar();
        assertEquals(OptionalLong.of(60), b.proximoVencimento(), "agora falta o 1, e o pacote 2 chegou em 10");
        t.em(60);
        b.retirar();
        assertEquals(OptionalLong.empty(), b.proximoVencimento());
    }

    // ---------- validações ----------

    @Test void argumentosInvalidos() {
        Relogio t = new Relogio();
        assertThrows(IllegalArgumentException.class, () -> new Solution.BufferDeJitter(-1, 10, t));
        assertThrows(IllegalArgumentException.class, () -> new Solution.BufferDeJitter(10, 0, t));
        assertThrows(IllegalArgumentException.class, () -> new Solution.BufferDeJitter(10, 10, null));
        Solution.BufferDeJitter b = new Solution.BufferDeJitter(10, 10, t);
        assertThrows(IllegalArgumentException.class, () -> b.receber(-1, "a"));
        assertThrows(IllegalArgumentException.class, () -> b.receber(0, null));
    }

    // ---------- volume ----------

    @Test void embaralhadoEmBlocosSaiSempreEmOrdem() {
        Relogio t = new Relogio();
        Solution.BufferDeJitter b = new Solution.BufferDeJitter(1_000_000, 100, t);
        Random rnd = new Random(7);
        List<Long> entregues = new ArrayList<>();
        for (int bloco = 0; bloco < 400; bloco++) {
            List<Long> seqs = new ArrayList<>();
            for (long s = bloco * 10L; s < bloco * 10L + 10; s++) seqs.add(s);
            Collections.shuffle(seqs, rnd);
            for (long s : seqs) {
                t.agora++;
                assertTrue(b.receber(s, "p" + s));
            }
            for (Solution.Entrega e : b.retirar()) {
                assertEquals(Solution.Entrega.Tipo.DADOS, e.tipo());
                entregues.add(e.seq());
            }
        }
        assertEquals(4000, entregues.size());
        for (int i = 0; i < entregues.size(); i++) assertEquals(i, entregues.get(i));
    }

    @Test void comPerdasAleatoriasCadaSeqSaiUmaVezEAsPerdasCoincidem() {
        Relogio t = new Relogio();
        Solution.BufferDeJitter b = new Solution.BufferDeJitter(1_000, 5_000, t);
        Random rnd = new Random(11);
        int total = 3000;
        boolean[] perdido = new boolean[total];
        for (int i = 0; i < total - 1; i++) perdido[i] = rnd.nextInt(10) == 0;   // o último nunca se perde
        List<Solution.Entrega> saida = new ArrayList<>();
        for (int bloco = 0; bloco < total / 10; bloco++) {
            List<Long> seqs = new ArrayList<>();
            for (long s = bloco * 10L; s < bloco * 10L + 10; s++) if (!perdido[(int) s]) seqs.add(s);
            Collections.shuffle(seqs, rnd);
            for (long s : seqs) b.receber(s, "p" + s);
            saida.addAll(b.retirar());
        }
        t.em(5_000);
        saida.addAll(b.retirar());

        assertEquals(total, saida.size());
        long perdas = 0;
        for (int i = 0; i < total; i++) {
            Solution.Entrega e = saida.get(i);
            assertEquals(i, e.seq());
            assertEquals(perdido[i], e.tipo() == Solution.Entrega.Tipo.PERDA, "seq " + i);
            if (perdido[i]) perdas++;
        }
        assertEquals(perdas, b.totalPerdas());
    }
}
